import{_ as o,a0 as i,w as l,s as m,I as a,x as r,ao as n,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"KDE 的19年進化歷程 | LCTT x X-CMD","titleTemplate":false,"description":"KDE 的19年進化歷程 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"KDE 的19年進化歷程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"KDE 的19年進化歷程 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20101020 19 Years of KDE History--Step by Step","title":"KDE 的19年進化歷程","tag":"201601","desc":""},"relativePath":"201601/20101020 19 Years of KDE History--Step by Step.md","filePath":"[post].md"}'),g={name:"201601/20101020 19 Years of KDE History--Step by Step.md"};function u(K,t,D,c,h,E){const p=i("Link");return l(),m("div",null,[t[18]||(t[18]=a("h1",{id:"kde-的19年進化歷程",tabindex:"-1"},[r("KDE 的19年進化歷程 "),a("a",{class:"header-anchor",href:"#kde-的19年進化歷程","aria-label":"Permalink to “KDE 的19年進化歷程”"},"​")],-1)),t[19]||(t[19]=a("p",null,"注：youtube 視頻",-1)),t[20]||(t[20]=a("iframe",{width:"660",height:"371",src:"https://www.youtube.com/embed/1UG4lQOMBC4?feature=oembed",frameborder:"0",allowfullscreen:""},null,-1)),t[21]||(t[21]=n('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h2><p>KDE – 史上功能最強大的桌面環境之一；開源且可自由使用。19年前，1996年10月14日，德國程序員 Matthias Ettrich 開始了這個美觀的桌面環境的開發。KDE 提供了用户界面以及其他很多日常使用的程序。今日，KDE 被成千上萬人在 Unix 和 Windows 上使用。19年，一個對軟件項目而言極為漫長的年歲。現在是時候讓我們回到最初，看看這一切肇始於何處。</p><p>K Desktop Environment（KDE）有很多創新之處：新設計，美觀，一致的體驗，易於使用，對普通用户和專業用户都足夠強大的應用庫。“KDE”這個名字是對單詞“通用桌面環境”（Common Desktop Environment）玩的一個簡單諧音遊戲，“K”即“Cool”。 第一代 KDE 在雙許可證授權下使用了 Trolltech 公司專利的 Qt framework（現 Qt 的前身），這兩個許可證分別是開源的 QPL（Q public license）和商業專利許可證（proprietary commercial license）。在2000年 Trolltech 公司讓一部分 Qt 軟件庫開始發佈在 GPL 證書下; Qt 4.5 發佈在了 LGPL 2.1 許可證下。自2009起 KDE 桌面環境由三部分構成：Plasma Workspaces（用做交互界面），KDE Applications，作為 KDE Software 編譯的 KDE Platform。</p><h2 id="各發布版本" tabindex="-1">各發布版本 <a class="header-anchor" href="#各發布版本" aria-label="Permalink to “各發布版本”">​</a></h2><h3 id="預發佈版本-–-1996年10月14日" tabindex="-1">預發佈版本 – 1996年10月14日 <a class="header-anchor" href="#預發佈版本-–-1996年10月14日" aria-label="Permalink to “預發佈版本 – 1996年10月14日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/0b3.png" alt=""></p><p>當時名稱為 Kool Desktop Environment；“Kool”這個單詞在很快就被棄用了。最初，所有 KDE 的組件都是被單獨發佈在開發社區裏的，它們並沒有被一個大的項目所貫穿起來。開發組郵件列表中的首選通信是發往kde@fiwi02.wiwi.uni-Tubingen.de 郵件列表。</p><h3 id="kde-1-0-–-1998年7月12日" tabindex="-1">KDE 1.0 – 1998年7月12日 <a class="header-anchor" href="#kde-1-0-–-1998年7月12日" aria-label="Permalink to “KDE 1.0 – 1998年7月12日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/10.png" alt=""></p><p>這個版本受到了頗有爭議的反饋。很多人反對使用 Qt 框架，因為當時的 FreeQt 許可證和自由軟件許可證並不兼容，他們建議開發組使用 Motif 或者 LessTif 替代。儘管有着這些反對聲，KDE 仍然被很多用户所青睞，並且成功作為第一個 Linux 發行版的環境被集成了進去。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/11.png" alt="28 January 1999"></p><p><em>1999年1月28日</em></p><p>有一次升級，<strong>K Desktop Environment 1.1</strong>，更快，更穩定的同時加入了很多小的改進。這個版本同時也加入了很多新的圖標，背景和材質紋理。和這些全面翻新同時出現的還有 Torsten Rahn 繪製的全新 KDE 圖標----一個放在齒輪前的字母 K ；這個圖標的修改版也一直沿用至今。</p><h3 id="kde-2-0-–-2000年10月23日" tabindex="-1">KDE 2.0 – 2000年10月23日 <a class="header-anchor" href="#kde-2-0-–-2000年10月23日" aria-label="Permalink to “KDE 2.0 – 2000年10月23日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/20.png" alt=""></p><p>重大更新：</p><ul><li>DCOP (Desktop COmmunication Protocol)，一個端到端的通信協議</li><li>KIO，一個應用程序 I/O 庫</li><li>KParts，組件對象模型</li><li>KHTML，一個符合 HTML 4.0 標準的渲染繪製引擎。</li></ul><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/21.png" alt="26 February 2001"></p><p><em>2001年2月26日</em></p><p><strong>K Desktop Environment 2.1</strong> 首次發佈了媒體播放器 noatun，它使用了模組化、插件設計。為了便利開發者，K Desktop Environment 2.1 打包了 KDevelop。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/22.png" alt="15 August 2001"></p><p><em>2001年8月15日</em></p><p><strong>KDE 2.2</strong>版本在 GNU/Linux 上加快了50%的應用啓動速度，同時提高了 HTML 渲染、JavaScript 穩定性和性能，同時還增加了一些 KMail 的功能。</p><h3 id="kde-3-0-–-2002年4月3日" tabindex="-1">KDE 3.0 – 2002年4月3日 <a class="header-anchor" href="#kde-3-0-–-2002年4月3日" aria-label="Permalink to “KDE 3.0 – 2002年4月3日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/30.png" alt=""></p><p>K Desktop Environment 3.0 加入了更好的限制使用功能，這個功能在電話亭、網咖，企業公用電腦上被廣泛需求，它可以禁止用户完全使用軟件的某些能力。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/31.png" alt="28 January 2003"></p><p><em>2003年1月28日</em></p><p><strong>K Desktop Environment 3.1</strong> 加入了新的默認窗口（Keramik）和圖標樣式（Crystal）和其他一些改進。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/32.png" alt="3 February 2004"></p><p><em>2004年2月3日</em></p><p><strong>K Desktop Environment 3.2</strong> 加入了諸如在網頁表格、書寫郵件中拼寫檢查的新功能；增強了郵件和日曆功能。完善了 Konqueror 中的標籤機制和對 Microsoft Windows 桌面共享協議（RDP）的支持。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/33.png" alt="19 August 2004"></p><p><em>2004年8月19日</em></p><p><strong>K Desktop Environment 3.3</strong> 側重於組合不同的桌面組件。Kontact 被放進了羣件應用 Kolab 並與 Kpilot 結合。Konqueror 的加入讓 KDE 有了更好的 IM 交流功能，比如支持發送文件，以及其他 IM 協議（如IRC）的支持。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/34.png" alt="16 March 2005"></p><p><em>2005年3月16日</em></p><p><strong>K Desktop Environment 3.4</strong> 側重於提高易用性。這次更新為 Konqueror、Kate、KPDF 加入了文字-語音轉換功能；也在桌面系統中加入了獨立的 KSayIt 文字-語音轉換軟件。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/35.png" alt="29 November 2005"></p><p><em>2005年11月29日</em></p><p><strong>The K Desktop Environment 3.5</strong> 發佈加入了 SuperKaramba，為桌面環境提供了易於安裝的插件（widgets）機制。 Konqueror 加入了廣告屏蔽功能併成為了有史以來第二個通過 Acid2 CSS 測試的瀏覽器。</p><h3 id="kde-sc-4-0-–-2008年1月11日" tabindex="-1">KDE SC 4.0 – 2008年1月11日 <a class="header-anchor" href="#kde-sc-4-0-–-2008年1月11日" aria-label="Permalink to “KDE SC 4.0 – 2008年1月11日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/400.png" alt=""></p><p>大部分的開發投身於把最新的技術和開發框架整合進 KDE 4 當中。Plasma 和 Oxygen 是兩次最大的用户界面風格變更。同時，Dolphin 替代 Konqueror 成為默認文件管理器，Okular 成為了默認文檔瀏覽器。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/401.png" alt="29 July 2008"></p><p><em>2008年7月29日</em></p><p><strong>KDE 4.1</strong> 引入了一個在 PIM 和 Kopete 中共享使用的表情主題系統；引入了可以讓用户便利地從互聯網上一鍵下載數據的 DXS。同時引入了 GStreamer、QuickTime 和 DirectShow 9 Phonon 後端。加入了新應用如：</p><ul><li>Dragon Player</li><li>Kontact</li><li>Skanlite — 掃描儀軟件</li><li>Step —— 物理模擬軟件</li><li>新遊戲: Kdiamond、Kollision、KBreakout 和更多......</li></ul><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/402.png" alt="27 January 2009"></p><p><em>2009年1月27日</em></p><p><strong>KDE 4.2</strong> 被認為是在已經極佳的 KDE 4.1 基礎上的又一次全面超越，同時也成為了大多數用户替換舊 3.5 版本的完美選擇。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/403.png" alt="4 August 2009"></p><p><em>2009年8月4日</em></p><p><strong>KDE 4.3</strong> 修復了超過10000個 bug，同時加入了讓近2000個用户要求的功能。整合一些新的技術例如：PolicyKit、NetworkManage &amp; Geolocation services 等也是這個版本的一大重點。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/404.png" alt="9 February 2010"></p><p><em>2010年2月9日</em></p><p><strong>KDE SC 4.4</strong> 基於 Qt 4 toolkit 的 4.6 版本，加入新的應用 KAddressBook。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/405.png" alt="10 August 2010"></p><p><em>2010年8月10日</em></p><p><strong>KDE SC 4.5</strong> 增加了一些新特性：整合了開源的瀏覽器引擎 WebKit 庫，其現在也在 Apple Safari 和 Google Chrome 中廣泛使用。KPackageKit 替換了 Kpackage。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/406.png" alt="26 January 2011"></p><p><em>2011年1月26日</em></p><p><strong>KDE SC 4.6</strong> 加強了 OpenGl 的性能，同時照常更新了無數bug和小改進。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/407.png" alt="27 July 2011"></p><p><em>2011年7月27日</em></p><p><strong>KDE SC 4.7</strong> 升級 KWin 以兼容 OpenGL ES 2.0 ，更新了 Qt Quick，Plasma Desktop 帶來許多增強和在應用裏的大量新特性， 修復了1.2萬個 bug。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/408.png" alt="25 January 2012"></p><p><em>2012年1月25日</em></p><p><strong>KDE SC 4.8</strong>: 更好的 KWin 性能與 Wayland 支持，更嶄新的 Doplhin 的外觀設計。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/409.png" alt="1 August 2012"></p><p><em>2012年8月1日</em></p><p><strong>KDE SC 4.9</strong>: 向 Dolphin 文件管理器增加了一些更新，比如重新加入了實時文件重命名，鼠標輔助按鈕支持，更好的位置面板和更多文件分類管理功能。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/410.png" alt="6 February 2013"></p><p><em>2013年2月6日</em></p><p><strong>KDE SC 4.10</strong>: 很多 Plasma 插件使用 QML 重寫； Nepomuk、Kontact 和 Okular 得到了很大程度的性能和功能提升。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/411.png" alt="14 August 2013"></p><p><em>2013年8月14日</em></p><p><strong>KDE SC 4.11</strong>: Kontact 和 Nepomuk 有了很多優化。 第一代 Plasma Workspaces 進入了單純維護階段。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/412.png" alt="18 December 2013"></p><p><em>2013年12月18日</em></p><p><strong>KDE SC 4.12</strong>: Kontact 得到了極大的提升，包括許多小的改進。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/413.png" alt="16 April 2014"></p><p><em>2014年4月16日</em></p><p><strong>KDE SC 4.13</strong>: Nepomuk 語義搜索功能替代了桌面上的原有的 Baloo 搜索。 KDE SC 4.13 以53個語言版本發佈。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/414.png" alt="20 August 2014"></p><p><em>2014年8月20日</em></p><p><strong>KDE SC 4.14</strong>: 這個發佈版本側重於穩定性提升：大量的 bug 修復和增加了一些小的功能。這是最後一個 KDE SC 4 發佈版本。</p><h3 id="kde-plasma-5-0-–-2014年7月15日" tabindex="-1">KDE Plasma 5.0 – 2014年7月15日 <a class="header-anchor" href="#kde-plasma-5-0-–-2014年7月15日" aria-label="Permalink to “KDE Plasma 5.0 – 2014年7月15日”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/500.png" alt=""></p><p>KDE Plasma 5 – 第五代 KDE。大幅改進了設計和系統，新的默認主題 Breeze 完全遷移到了 QML，更好的 OpenGL 性能，更完美的 HiDPI （高分辨率）顯示支持。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/501.png" alt="11 November 2014"></p><p><em>2014年11月11日</em></p><p><strong>KDE Plasma 5.1</strong>：遷移了從 Plasma 4 裏丟失的功能。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/502.png" alt="27 January 2015"></p><p><em>2015年1月27日</em></p><p><strong>KDE Plasma 5.2</strong>：新組件：BlueDevil、KSSHAskPass、Muon、SDDM 主題設置、KScreen、GTK+ 樣式設置和 KDecoration。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/503.png" alt="28 April 2015"></p><p><em>2015年4月28日</em></p><p><strong>KDE Plasma 5.3</strong>：Plasma Media Center 技術預覽。新的藍牙和觸摸板小程序；改良了電源管理。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/KDE_History/im/504.png" alt="25 August 2015"></p><p><em>2015年8月25日</em></p><p><strong>KDE Plasma 5.4</strong>：Wayland 登場，新的基於 QML 的音頻管理程序，一個全屏的程序啓動器替代品。</p>',102)),a("p",null,[t[2]||(t[2]=r("萬分感謝 ",-1)),e(p,{href:"https://www.kde.org/"},{default:s(()=>[...t[0]||(t[0]=[r("KDE",-1)])]),_:1}),t[3]||(t[3]=r(" 開發者及社區，並感謝 Wikipedia 為書寫 ",-1)),e(p,{href:"https://en.wikipedia.org/wiki/KDE_Plasma_5"},{default:s(()=>[...t[1]||(t[1]=[r("概述",-1)])]),_:1}),t[4]||(t[4]=r(" 帶來的幫助，同時，感謝所有讀者。讓我們保持自由精神（be free）並繼續支持如同 KDE 一樣的開源的自由軟件發展。",-1))]),t[22]||(t[22]=a("hr",null,null,-1)),a("p",null,[t[6]||(t[6]=r("via: ",-1)),e(p,{href:"https://tlhp.cf/kde-history/"},{default:s(()=>[...t[5]||(t[5]=[r("https://tlhp.cf/kde-history/",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=r("作者：",-1)),e(p,{href:"https://tlhp.cf/author/paul/"},{default:s(()=>[...t[7]||(t[7]=[r("Pavlo Rudyi",-1)])]),_:1}),t[11]||(t[11]=r(" 譯者：",-1)),e(p,{href:"https://github.com/Moelf"},{default:s(()=>[...t[8]||(t[8]=[r("Moelf",-1)])]),_:1}),t[12]||(t[12]=r(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:s(()=>[...t[9]||(t[9]=[r("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=r("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[13]||(t[13]=[r("LCTT",-1)])]),_:1}),t[16]||(t[16]=r(" 原創編譯，",-1)),e(p,{href:"https://linux.cn/"},{default:s(()=>[...t[14]||(t[14]=[r("Linux中國",-1)])]),_:1}),t[17]||(t[17]=r(" 榮譽推出",-1))])])}const k=o(g,[["render",u]]);export{b as __pageData,k as default};
